import mammoth from 'mammoth';
import TurndownService from 'turndown';
import { gfm } from 'turndown-plugin-gfm';

export interface DocxToMdResult {
  markdown: string;
  warnings: string[];
}

/**
 * Normalizes HTML tables generated by Mammoth:
 * 1. Promotes the first row to <th> if no <th> tags are present so Turndown GFM treats it as a table
 * 2. Unwraps <p> tags inside table cells and collapses newlines, ensuring each row remains strictly on a single line in Markdown
 * 3. Escapes any raw pipe '|' characters in cells to avoid broken table column delimiters
 */
function sanitizeTablesInHtml(html: string): string {
  return html.replace(/<table(\b[^>]*)>([\s\S]*?)<\/table>/gi, (tableMatch: string, tableAttrs: string, tableInner: string) => {
    const hasTh = /<th\b/i.test(tableInner);
    let processedInner = tableInner;

    if (!hasTh) {
      let firstRowReplaced = false;
      processedInner = processedInner.replace(/<tr(\b[^>]*)>([\s\S]*?)<\/tr>/i, (rowMatch: string, rowAttrs: string, rowInner: string) => {
        if (!firstRowReplaced) {
          firstRowReplaced = true;
          const thRow = rowInner.replace(/<td(\b[^>]*)>([\s\S]*?)<\/td>/gi, '<th$1>$2</th>');
          return `<tr${rowAttrs}>${thRow}</tr>`;
        }
        return rowMatch;
      });
    }

    processedInner = processedInner.replace(/<(th|td)(\b[^>]*)>([\s\S]*?)<\/\1>/gi, (cellMatch: string, tag: string, attrs: string, cellInner: string) => {
      let text = cellInner
        .replace(/<p\b[^>]*>/gi, '')
        .replace(/<\/p>/gi, '<br>')
        .replace(/(<br\s*\/?>)+$/gi, '')
        .replace(/[\r\n]+/g, ' ')
        .replace(/\s{2,}/g, ' ')
        .replace(/(?<!\\)\|/g, '\\|')
        .trim();
      return `<${tag}${attrs}>${text}</${tag}>`;
    });

    return `<table${tableAttrs}>${processedInner}</table>`;
  });
}

export async function convertDocxToMarkdown(docxBuffer: Buffer): Promise<DocxToMdResult> {
  const warnings: string[] = [];

  // Style map to accurately detect Word built-in and custom headings & code styles
  const styleMap = [
    "p[style-name='Heading 1'] => h1:fresh",
    "p[style-name='Heading 2'] => h2:fresh",
    "p[style-name='Heading 3'] => h3:fresh",
    "p[style-name='Heading 4'] => h4:fresh",
    "p[style-name='Heading 5'] => h5:fresh",
    "p[style-name='Heading 6'] => h6:fresh",
    "p[style-name='Title'] => h1:fresh",
    "p[style-name='Subtitle'] => h2:fresh",
    "p[style-name='Quote'] => blockquote:fresh",
    "p[style-name='Blockquote'] => blockquote:fresh",
    "p[style-name='Code Block'] => pre:fresh",
    "p[style-name='Code'] => pre:fresh",
    "r[style-name='Code'] => code",
    "r[style-name='Inline Code'] => code",
    "r[style-name='Strike'] => del",
    "r[style-name='Strikethrough'] => del",
    // Table of Contents (TOC) mappings
    "p[style-name='TOC Heading'] => h2:fresh",
    "p[style-id='TOCHeading'] => h2:fresh",
    "p[style-name='toc 1'] => p:fresh",
    "p[style-id='TOC1'] => p:fresh",
    "p[style-name='toc 2'] => p:fresh",
    "p[style-id='TOC2'] => p:fresh",
    "p[style-name='toc 3'] => p:fresh",
    "p[style-id='TOC3'] => p:fresh",
    "p[style-name='toc 4'] => p:fresh",
    "p[style-id='TOC4'] => p:fresh",
  ];

  const mammothOptions = {
    styleMap,
    convertImage: mammoth.images.imgElement((image) => {
      return image.read('base64').then((imageBuffer) => {
        return {
          src: `data:${image.contentType};base64,${imageBuffer}`,
        };
      });
    }),
  };

  const mammothResult = await mammoth.convertToHtml({ buffer: docxBuffer }, mammothOptions);

  if (mammothResult.messages && mammothResult.messages.length > 0) {
    for (const msg of mammothResult.messages) {
      if (msg.type === 'warning') {
        warnings.push(`Word document parsing: ${msg.message}`);
      }
    }
  }

  // Setup Turndown with GitHub Flavored Markdown
  const turndownService = new TurndownService({
    headingStyle: 'atx',
    hr: '---',
    bulletListMarker: '-',
    codeBlockStyle: 'fenced',
    emDelimiter: '*',
    strongDelimiter: '**',
  });

  // Enable GFM plugin (tables, strikethrough, task lists)
  turndownService.use(gfm);

  // Custom rule for inline code tags inside pre
  turndownService.addRule('preCode', {
    filter: ['pre'],
    replacement: function (content: string, node: any) {
      const codeElement = node.querySelector ? node.querySelector('code') : null;
      const codeContent = codeElement ? codeElement.textContent : node.textContent;
      const lang = (node.getAttribute && node.getAttribute('data-language')) || '';
      return `\n\n\`\`\`${lang}\n${codeContent.trim()}\n\`\`\`\n\n`;
    },
  });

  // Pre-process HTML tables so Mammoth's paragraph tags don't break GFM Markdown table rows
  const cleanedHtml = sanitizeTablesInHtml(mammothResult.value);

  // Convert HTML to Markdown
  let markdown = turndownService.turndown(cleanedHtml);

  // Normalize excessive blank lines (more than 2 consecutive newlines)
  markdown = markdown.replace(/\n{3,}/g, '\n\n').trim();

  return {
    markdown,
    warnings,
  };
}
